import{_ as r,a as l,b as t}from"./chunks/2472d837de6cd4f056bf.DY7bboP3.js";import{_ as o,C as i,o as n,c as s,j as a,a as h,E as c,a5 as d}from"./chunks/framework.DNkHA0lr.js";const P=JSON.parse('{"title":"消失一段时间，带着脱胎换骨的自己回归（改变人生的12条法则）","description":"","frontmatter":{"title":"消失一段时间，带着脱胎换骨的自己回归（改变人生的12条法则）","originalTitle":"Disappear And Come Back Unrecognizable (12 Rules To Change Your Life)","date":"2024-04-06","originalUrl":"https://thedankoe.com/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life/","minutes":8,"sourceHash":"b5af1d88234daa54187f46447ee57fa7ef5d5b04ec6b1809f841986c2b2edc28","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life/"}]]},"headers":[],"relativePath":"letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life.md","filePath":"letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life.md"}'),u={name:"letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life.md"};function m(b,e,f,g,k,_){const p=i("ArticleMeta");return n(),s("div",null,[e[0]||(e[0]=a("h1",{id:"消失一段时间-带着脱胎换骨的自己回归-改变人生的12条法则",tabindex:"-1"},[h("消失一段时间，带着脱胎换骨的自己回归（改变人生的12条法则） "),a("a",{class:"header-anchor",href:"#消失一段时间-带着脱胎换骨的自己回归-改变人生的12条法则","aria-label":'Permalink to "消失一段时间，带着脱胎换骨的自己回归（改变人生的12条法则）"'},"​")],-1)),c(p),e[1]||(e[1]=d('<p><a href="https://www.youtube.com/embed/reLmDf_PIvI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>我说这话不是为了显得傲慢。</p><p>但在明确未来想要什么这件事上，我从来没有任何问题。</p><p>当人们说“我不知道我想要什么”时，他们真正的意思是“我不想为了得到我想要的东西而付出努力。”</p><p>并不是你不知道自己想要什么。而是你知道自己不想要什么——这意味着你知道自己想要什么——但你在逃避摆脱它所必须付出的代价。</p><p>我一直知道自己想要什么，因为观察社会并弄清楚我不想要什么，是极其简单的事：</p><ul><li>我讨厌的职位</li><li>我讨厌的工作</li><li>我讨厌的身体</li><li>我讨厌的伴侣</li><li>一个与我作对的大脑</li></ul><p>单凭这一点，很容易就能弄清楚我必须做什么：</p><ul><li>无论失败多少次都要成为一名创业者（我经历了7次失败）</li><li>获得摆脱我不想做的工作的权力（在社交媒体上写作以获得杠杆）</li><li>去健身房并注重营养</li><li>让这3件事在生活的各个领域开启更多机会</li><li>让这条路径通过责任的渐进超载（progressive overload）创造出平静的心态。当你变得更强壮时，负重就会感觉更轻。</li></ul><p>每个人都知道，这条道路的某种形式就是他们注定要去做的事。</p><p>你的心灵渴望自我实现和超越。你存在的深处想要这些东西，但你的自我（ego）却被它以为自己想要的东西分心了。</p><p>这就是问题所在。</p><p>你没有办法集中注意力。</p><p>你没有一个对未来的规划，其引力足以大过你生活中的那些干扰。</p><p>你挣扎于维持长远的视野，从而陷入了永无止境、引发焦虑的短期任务中。</p><p>如果能有一个单一的框架来决定你全部的成功，那会是什么感觉？一个无论何时你感到迷茫都能参考的框架？</p><p>这就是我们要讨论的内容。</p><h2 id="创造的12条法则" tabindex="-1">创造的12条法则 <a class="header-anchor" href="#创造的12条法则" aria-label="Permalink to &quot;创造的12条法则&quot;">​</a></h2><blockquote><p>你需要一个计划。因为如果你没有，社会就会有，而且社会在过去几十年里一直都在规划你的人生。—— <a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》（The Art of Focus）</a></p></blockquote><p><img src="'+l+'" alt=""></p><p>从你出生的那一天起，社会就为你分配了目标。</p><p>这些目标随后框定了你认知世界的方式。</p><p>你学习技能以实现这些目标。你识别与这些目标一致的机会。你在生活中经历的一切，都是透过指导大脑中系统形成的有意识或无意识目标的镜头，来体验生活中的一切。</p><p>如果我们想建立一个充满意义、财富和影响力的生活，我们必须追求理想的未来，创造一个值得讲述的故事，并把这条路传承给那些准备好接受它的人。</p><p>在创造性成功与失败之间徘徊了十年之后，我发现了一个能在你做的任何事情中为你带来成功的大局框架。</p><p>这些模式存在于营销、销售、人类行为、巅峰表现、心理学、故事、游戏、十亿美元公司的结构、成功的产品开发，以及任何涉及创造和分配价值过程的事物中。</p><p>你将把它作为你人生的指路明灯，但我鼓励你深思如何将其应用到你的业务、人际关系和对话中。</p><h3 id="反向愿景" tabindex="-1"><strong>反向愿景</strong> <a class="header-anchor" href="#反向愿景" aria-label="Permalink to &quot;**反向愿景**&quot;">​</a></h3><p>我们的故事从反向愿景开始。</p><p>那个令你痛苦的根源。</p><p>你将要培养的世界观的第一个极端。</p><p>一个能把你踢进行动状态的积极恐惧机制。</p><p><em>你的反向愿景就是你不想过的未来。</em></p><p>开始记录你不想重复的经历。</p><ul><li>你不在乎学习的材料。</li><li>你懒得完成的工作。</li><li>你不希望发生的争吵。</li></ul><p>你不可能在一瞬间摆脱它们。</p><p>你的目的是把它们识别为需要解决的问题。</p><h3 id="愿景" tabindex="-1"><strong>愿景</strong> <a class="header-anchor" href="#愿景" aria-label="Permalink to &quot;**愿景**&quot;">​</a></h3><p>如果你没有愿景，你就会迷失。</p><p>你无法创造结果，所以你注定只能在已被决定的结果中机械地活着。</p><p>你在生活各个领域做出的每一个决定，都必须经过愿景的过滤。</p><p>这就是你为行动赋予意义并最小化干扰的方式。</p><p>准确写下你想从生活中得到什么。</p><p><em>不要漏掉任何细节，但要意识到这是一个迭代的过程。</em></p><p>第一次尝试你不会完全写对，而且可能永远也不会完美。这不是重点。花30分钟构建一个“最小可行愿景”。经常回看它进行增删和改进，因为你的欲望必然会随着你的失败而改变。</p><h3 id="使命" tabindex="-1"><strong>使命</strong> <a class="header-anchor" href="#使命" aria-label="Permalink to &quot;**使命**&quot;">​</a></h3><p>你的使命是你生命中最重要的东西。</p><p>它是连接你想要和不想要的事物之间的桥梁。</p><p>是你通向愿景所开辟的道路。</p><p><em>任何与你的使命不符的事物都要被视为干扰。</em></p><p>你的使命会随着你对新信念、新机会和新知识的认知而演变。</p><p>你的使命需要信念。除非你迈出第一步，否则你看不到下一步。而一旦你迈出了，第二步可能完全不同于你的任何想象。</p><h3 id="标准" tabindex="-1"><strong>标准</strong> <a class="header-anchor" href="#标准" aria-label="Permalink to &quot;**标准**&quot;">​</a></h3><p>你没有到达你想去的地方，因为你安于现状。</p><p><em>你不需要向处境屈服，你接受它，以便能继续前进。</em></p><p>标准是从你的环境中吸收的。</p><ul><li>你交往的朋友。</li><li>你阅读的书籍。</li><li>你消费的媒体。</li><li>抚养你长大的父母。</li><li>那些无所不知的老师。</li></ul><p>或许是时候做出改变，并承受随之而来的后果了。</p><h3 id="目标" tabindex="-1"><strong>目标</strong> <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;**目标**&quot;">​</a></h3><p>大目标指引方向。小目标提供清晰度。</p><p>当摆在面前的任务简单到让你忍不住想去完成它时，你不需要动力。</p><p>把你的愿景分解为以十年、年、月、周和日为单位的目标。</p><p>它们是你的向导，而不是你的主人。</p><p>在愿景上要固执，在细节上要灵活。</p><p>你的目标会随着你的改变而改变，去接受这一点。</p><h3 id="项目" tabindex="-1"><strong>项目</strong> <a class="header-anchor" href="#项目" aria-label="Permalink to &quot;**项目**&quot;">​</a></h3><p>学习源于挣扎，而非死记硬背。</p><p>你需要构建一系列具体的项目，以此来实现你的愿景。</p><ul><li>将目标转化为项目。</li><li>构思大纲。</li><li>确定里程碑。</li><li>设定截止日期。</li><li>规划需要研究的领域。</li></ul><p>先建设，再学习。启动项目，暴露你在知识和技能上的匮乏，然后以此作为你自我教育的参考点。</p><h3 id="教育" tabindex="-1"><strong>教育</strong> <a class="header-anchor" href="#教育" aria-label="Permalink to &quot;**教育**&quot;">​</a></h3><p>你没达到你想去的层次，因为你并没有自己以为的那么聪明。</p><p>每一个项目，都需要特定的技能组合和心态才能完成。</p><p>每天自我教育必须成为你生活中的基石习惯。如果你停止学习，你就会停止进化。机会不再出现，你会被困在当前的发展阶段。</p><p>教育是实验的燃料。</p><h3 id="限制" tabindex="-1"><strong>限制</strong> <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;**限制**&quot;">​</a></h3><p>蠢货变富的代价是牺牲生活中所有美好的事物。</p><p>创作者变富的代价则是他自己的选择。</p><p>对目标的限制能逼出创造力。</p><p>问题是，为了实现目标，你<em>不</em>愿意牺牲什么？</p><p>当你试图在不背叛愿景的情况下实现目标时，创造性的挑战就出现了。</p><p>你可以变富而不牺牲你的家庭。</p><p>你可以变健康而不牺牲你的工作。</p><p>你可以变得有价值，而不牺牲那些让生活值得一过的东西。</p><h3 id="杠杆" tabindex="-1"><strong>杠杆</strong> <a class="header-anchor" href="#杠杆" aria-label="Permalink to &quot;**杠杆**&quot;">​</a></h3><p>每天，你都需要一些优先任务，从根基做起，拨动杠杆，推动你的项目、目标和愿景。</p><p>如果不去培养精通感，这些往往会被视为枯燥的基本功。</p><p>做该做的事，但要把你的愿景当作驶入未知领域的锚。如果你没有取得进展，那是因为你没有撬动杠杆，哪怕你以为你撬动了。</p><p>写作是我的创作者业务（以及几乎所有其他现代商业）中的主要杠杆。这是我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>中教授的内容，也是我们在<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a>里帮助那些渴望获得个性化帮助和反馈的人所做的事。</p><h3 id="挑战" tabindex="-1"><strong>挑战</strong> <a class="header-anchor" href="#挑战" aria-label="Permalink to &quot;**挑战**&quot;">​</a></h3><p>当新手与大师对弈时，双方都不会觉得有趣。</p><p>新手会感到焦虑，而大师会感到无聊。</p><p>当你的技能完美匹配当前局势的挑战时，世界变得安静，你将优雅地向前推进。</p><p>挑战是乐趣的源泉。</p><p>乐趣就存在于无聊与焦虑之间的走钢丝上。在你能力的边缘地带。</p><p>通往有意义生活的道路，通常就存在于一次简单的视角转换中。</p><h3 id="好奇心" tabindex="-1"><strong>好奇心</strong> <a class="header-anchor" href="#好奇心" aria-label="Permalink to &quot;**好奇心**&quot;">​</a></h3><p>要乐于偏离航线去发现新的潜能。</p><p>我们太容易把自己锁死在那个原本试图逃离的机械化常规之中。</p><p>保持好奇。</p><p>深入挖掘你的兴趣。</p><p>别让太多问题悬而未决。</p><p>避免被锁定在那些将你的思维局限于一条被盲目崇拜的道路上的范式和信念中。</p><p>你的愿景就像一块电池。你必须用经验、教育和“误入歧途”来为它充能。</p><h3 id="实验" tabindex="-1"><strong>实验</strong> <a class="header-anchor" href="#实验" aria-label="Permalink to &quot;**实验**&quot;">​</a></h3><p>如果你只做跟别人一样的事，你注定只能得到跟别人一样的结果。</p><ul><li>研究别人教授的流程，就是那些他们借此取得成功的流程。</li><li>尝试多种技术，看看哪种能给<em>你</em>带来最佳结果。</li><li>创建一套你自己能够保持一致的专属流程。</li></ul><p>在健身中，尝试不同的训练和营养计划。在人际关系中，尝试心理治疗或自助书籍。在商业中，尝试冷外联和自然流量内容。</p><p>避免对某一种绝对正确的道路变得教条。没有绝对正确的方法，只有你自己的方法，而且它绝不是一成不变的，因为游戏的不同阶段需要不同的方法来通关。</p><p>当你迷茫时，过一遍这个流程。</p><p>当你的人际关系受挫时，过一遍这个流程。当你的业务无法起步时，过一遍这个流程。</p><p>每一次与现实的成功交互，都始于并终于对所求之物的清晰图景、对如何实现的明确认知，以及为了获取稀有结果的创造性执行。</p><h2 id="做出更好的决定" tabindex="-1">做出更好的决定 <a class="header-anchor" href="#做出更好的决定" aria-label="Permalink to &quot;做出更好的决定&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>你没有达到你想去的层次，因为：</p><ul><li>你没有做出那些通向有目标感的事业的选择。</li><li>你没有做出那些通向令人满足的人际关系的选择。</li><li>你没有做出那些通向健康且富有美感的身体的选择。</li></ul><p>此时此刻的你，就是你过去选择的化身。</p><p>所以，如果你想掌控自己将成为什么样的人，你的选择至关重要。</p><p>这里有两件事：</p><ol><li>你想成为谁——视角与拉远视野。</li><li>将你带到那里的选择——感知与拉近焦点。</li></ol><p>好的生活，是通过不断提醒自己的愿景，并通过一致的行动来塑造能将其实现的身份而创造出来的。</p><p>更好的决定来自于视角和感知。</p><p>每天拉远视野，提醒自己你不想要什么。你不需要关注你想要什么，因为那会通过你的选择自然显现出来。</p><p>在你的脑海中把持住这个框架。</p><p>不要让干扰渗透进来。</p><p>任何时候面临选择，拉远视野并进行对齐。</p><p>“这会有益于我试图创造的未来吗？”</p><p>然后，果断一点。做出决定。</p><p>允许失败进入你的生活,这样你才能在下一次纠正自己的行为。</p><p>觉知是一种治愈。</p><p>你不必戒掉所有的坏习惯。你只需要用你愿景的视角去审视它们和它们的后果,坚持足够长的时间。</p><p>Dan</p><hr><p><a href="/en/letters/disappear-and-come-back-unrecognizable-12-rules-to-change-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',135))])}const T=o(u,[["render",m]]);export{P as __pageData,T as default};
